#!/usr/bin/env python3
"""Self-extracting recipe wiki tooling. First run unpacks payloads then re-execs."""
from __future__ import annotations

import base64
import gzip
import os
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
MARKER = HERE / ".recipe_wiki_payload_extracted"

PY_B64 = """"""
HTML_B64 = """"""


def extract(b64: str, dest: Path) -> None:
    dest.write_bytes(gzip.decompress(base64.b64decode(b64)))


def main() -> None:
    extract(PY_B64, HERE / "build_recipe_wiki.py")
    extract(HTML_B64, HERE / "recipe_wiki_template.html")
    MARKER.write_text("ok\n", encoding="utf-8")
    os.execv(sys.executable, [sys.executable, str(HERE / "build_recipe_wiki.py"), *sys.argv[1:]])


if __name__ == "__main__":
    main()
